const input = $json;

const TOKEN = String(input.githubToken || '').trim();
const OWNER = String(input.githubOwner || '').trim();
const REPO = String(input.githubRepo || '').trim();
const BRANCH = String(input.githubBranch || 'main').trim();
const CSV_PATH = String(input.csvPath || 'data/scraped-listings.csv').trim();
const CRAWL4AI_URL = String(input.crawl4aiUrl || '').trim();
const DEFAULT_BASE = String(input.defaultBaseUrl || 'https://www.jacars.net').trim().replace(/\/$/, '');
const COUNTRY_FILTER = String(input.countryFilter || 'Jamaica').trim().toLowerCase();
const BATCH_SIZE = Math.max(1, Number(input.batchSize || 12));
const MAX_ROWS = Math.max(1, Number(input.maxRowsToBackfill || 300));

if (!TOKEN || !OWNER || !REPO || !CSV_PATH || !CRAWL4AI_URL) {
  throw new Error('Missing required config. Fill githubToken, githubOwner, githubRepo, csvPath, crawl4aiUrl.');
}

const ghHeaders = {
  authorization: `Bearer ${TOKEN}`,
  accept: 'application/vnd.github+json',
  'x-github-api-version': '2022-11-28'
};

const csvHeaders = ['id','status','target_surface','app_category','app_subcategory','title','price_text','price_value','currency','city','country','seller','phone','description','image_urls','source_site','source_url','scraped_at','make','model','trim','year','condition','transmission','color','mileage_km','attributes','source_availability','source_availability_checked_at','source_http_status','source_unavailable_reason','source_last_seen_at','source_resolved_url','source_miss_count','source_miss_recorded_at','sync_visibility','sync_visibility_reason'];

const csvEscape = (value = '') => {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};

const parseCsv = (text = '') => {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  const pushCell = () => { row.push(cell); cell = ''; };
  const pushRow = () => { pushCell(); rows.push(row); row = []; };
  const inputText = String(text || '').replace(/^\uFEFF/, '');

  for (let i = 0; i < inputText.length; i += 1) {
    const char = inputText[i];
    const next = inputText[i + 1];
    if (quoted) {
      if (char === '"' && next === '"') { cell += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else cell += char;
    } else if (char === '"') {
      quoted = true;
    } else if (char === ',') {
      pushCell();
    } else if (char === '\n') {
      pushRow();
    } else if (char !== '\r') {
      cell += char;
    }
  }

  if (cell || row.length) pushRow();
  const headers = (rows.shift() || csvHeaders).map((h) => String(h || '').trim());
  return rows
    .filter((values) => values.some((v) => String(v || '').trim()))
    .map((values) => headers.reduce((acc, header, index) => {
      if (header) acc[header] = values[index] || '';
      return acc;
    }, {}));
};

const toCsv = (rows = []) => {
  const headerLine = csvHeaders.join(',');
  const body = rows.map((row) => csvHeaders.map((h) => csvEscape(row[h] || '')).join(','));
  return [headerLine, ...body].join('\n') + '\n';
};

const absUrl = (value = '', base = DEFAULT_BASE) => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith('//')) return `https:${raw}`;
  if (raw.startsWith('/')) return `${base}${raw}`;
  return `${base}/${raw}`;
};

const normalizeUrl = (value = '') => {
  const url = String(value || '').trim();
  if (!url) return '';
  return url.replace(/#.*$/, '').replace(/\/$/, '');
};

const decode = (value = '') => String(value || '')
  .replace(/&quot;/g, '"')
  .replace(/&#34;/g, '"')
  .replace(/&amp;/g, '&')
  .replace(/&#x2F;/g, '/');

const normalizePhone = (value = '') => String(value || '')
  .replace(/[\s()-.]/g, '')
  .replace(/^00/, '+')
  .trim();

const extractPhone = (text = '') => {
  const html = String(text || '');

  const wa = html.match(/api\.whatsapp\.com\/send\?phone=([^&"']+)/i);
  if (wa?.[1]) return normalizePhone(decodeURIComponent(wa[1]));

  const tel = html.match(/href=["']tel:([^"']+)["']/i);
  if (tel?.[1]) return normalizePhone(decodeURIComponent(tel[1]));

  const rawPhone = html.match(/(?:\+?1[-\s]?)?\(?\d{3}\)?[-\s]?\d{3}[-\s]?\d{4}/);
  if (rawPhone?.[0]) return normalizePhone(rawPhone[0]);

  const masked = html.match(/phone-author-subtext__main[^>]*>([^<]+)<[\s\S]{0,140}?phone-author-subtext__mask[^>]*>([^<]*)</i);
  if (masked?.[1]) return normalizePhone(`${masked[1]}${masked[2] || ''}`);

  return '';
};

const normalizeCrawlItems = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(normalizeCrawlItems);
  if (Array.isArray(value.results)) return value.results;
  if (Array.isArray(value.data)) return value.data;
  if (value.body) return normalizeCrawlItems(value.body);
  return [value];
};

const getGithubCsv = async () => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}?ref=${BRANCH}`;
  const res = await this.helpers.httpRequest({
    url,
    headers: ghHeaders,
    json: true,
    resolveWithFullResponse: true,
    simple: false
  });
  const status = Number(res?.statusCode || res?.status || 200);
  if (status === 404) return { sha: null, text: csvHeaders.join(',') + '\n' };
  if (status < 200 || status >= 300) throw new Error(`Could not read ${CSV_PATH}: ${status}.`);
  const metadata = res?.body ?? res;
  if (!metadata?.sha) throw new Error('GitHub did not return a CSV blob SHA.');
  let encoded = String(metadata.content || '').replace(/\n/g, '');
  if (!encoded || String(metadata.encoding || '').toLowerCase() !== 'base64') {
    const blobRes = await this.helpers.httpRequest({
      url: `https://api.github.com/repos/${OWNER}/${REPO}/git/blobs/${metadata.sha}`,
      headers: ghHeaders,
      json: true,
      resolveWithFullResponse: true,
      simple: false
    });
    const blobStatus = Number(blobRes?.statusCode || blobRes?.status || 200);
    if (blobStatus < 200 || blobStatus >= 300) throw new Error(`Could not read ${CSV_PATH} blob: ${blobStatus}.`);
    const blob = blobRes?.body ?? blobRes;
    encoded = String(blob?.content || '').replace(/\n/g, '');
  }
  if (!encoded) throw new Error('GitHub returned an empty CSV blob; refusing to overwrite existing listings.');
  const text = Buffer.from(encoded, 'base64').toString('utf8');
  if (!text.trim()) throw new Error('GitHub returned an empty CSV; refusing to overwrite existing listings.');
  return { sha: metadata.sha, text };
};
const putGithubCsv = async (text, sha) => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}`;
  const body = {
    message: 'Backfill missing phone numbers in scraped listings CSV',
    branch: BRANCH,
    content: Buffer.from(text, 'utf8').toString('base64'),
    ...(sha ? { sha } : {})
  };
  return this.helpers.httpRequest({
    url,
    method: 'PUT',
    headers: { ...ghHeaders, 'content-type': 'application/json' },
    body,
    json: true
  });
};

const crawlBatch = async (urls) => {
  const response = await this.helpers.httpRequest({
    url: CRAWL4AI_URL,
    method: 'POST',
    body: {
      urls,
      browser_config: { type: 'BrowserConfig', params: { headless: true } },
      crawler_config: { type: 'CrawlerRunConfig', params: { stream: false, cache_mode: 'bypass' } }
    },
    json: true
  });
  return normalizeCrawlItems(response.body || response);
};

const existing = await getGithubCsv.call(this);
const rows = parseCsv(existing.text);

const candidates = rows
  .map((row, idx) => ({ row, idx }))
  .filter(({ row }) => {
    const country = String(row.country || '').trim().toLowerCase();
    const phone = String(row.phone || '').trim();
    const sourceUrl = String(row.source_url || '').trim();
    return country === COUNTRY_FILTER && !phone && !!sourceUrl;
  })
  .slice(0, MAX_ROWS);

if (!candidates.length) {
  return [{ json: { status: 'no-op', message: 'No Jamaica rows with missing phone.', updated: 0 } }];
}

const candidateUrls = [...new Set(candidates.map(({ row }) => normalizeUrl(absUrl(row.source_url))))].filter(Boolean);

const detailsByUrl = new Map();
let crawled = 0;
for (let i = 0; i < candidateUrls.length; i += BATCH_SIZE) {
  const batch = candidateUrls.slice(i, i + BATCH_SIZE);
  const details = await crawlBatch.call(this, batch);
  crawled += batch.length;

  for (const item of details) {
    const detailUrl = normalizeUrl(item.url || item.redirected_url || '');
    const body = item.html || item.cleaned_html || item.fit_html || item.markdown?.raw_markdown || item.markdown || item.fit_markdown || '';
    if (!detailUrl || !body) continue;
    detailsByUrl.set(detailUrl, body);
  }
}

let updated = 0;
for (const { row } of candidates) {
  const key = normalizeUrl(absUrl(row.source_url));
  const body = detailsByUrl.get(key);
  if (!body) continue;
  const phone = extractPhone(body);
  if (!phone) continue;
  row.phone = phone;
  updated += 1;
}

if (updated > 0) {
  const csv = toCsv(rows);
  await putGithubCsv.call(this, csv, existing.sha);
}

return [{
  json: {
    status: updated > 0 ? 'updated' : 'completed_no_numbers_found',
    totalRows: rows.length,
    candidates: candidates.length,
    crawledUrls: crawled,
    updated,
    country: input.countryFilter || 'Jamaica',
    csvPath: CSV_PATH
  }
}];
